import{_ as t,c as o,o as a,ag as i}from"./chunks/framework.dvv-DFtf.js";const g=JSON.parse('{"title":"Log Viewer","description":"","frontmatter":{},"headers":[],"relativePath":"features/log-viewer.md","filePath":"features/log-viewer.md"}'),r={name:"features/log-viewer.md"};function l(s,e,n,d,c,h){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="log-viewer" tabindex="-1">Log Viewer <a class="header-anchor" href="#log-viewer" aria-label="Permalink to &quot;Log Viewer&quot;">​</a></h1><p>The Log Viewer provides real-time log streaming from pods and containers with powerful viewing options.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Access the Log Viewer by pressing <code>L</code> on any pod, deployment, or container. Logs stream in real-time, letting you monitor application output as it happens.</p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><h3 id="real-time-streaming" tabindex="-1">Real-Time Streaming <a class="header-anchor" href="#real-time-streaming" aria-label="Permalink to &quot;Real-Time Streaming&quot;">​</a></h3><p>Logs stream live from your containers:</p><ul><li>New log entries appear instantly</li><li>Auto-scroll keeps you at the latest output</li><li>Pause streaming to inspect specific entries</li></ul><h3 id="syntax-highlighting" tabindex="-1">Syntax Highlighting <a class="header-anchor" href="#syntax-highlighting" aria-label="Permalink to &quot;Syntax Highlighting&quot;">​</a></h3><p>Log output is automatically syntax highlighted:</p><ul><li>JSON log entries are formatted and colored</li><li>Best effort for log levels (INFO, WARN, ERROR) and other fields like timestamp to be color-coded</li></ul><h3 id="formatting-copy" tabindex="-1">Formatting &amp; Copy <a class="header-anchor" href="#formatting-copy" aria-label="Permalink to &quot;Formatting &amp; Copy&quot;">​</a></h3><p>Click on the <code>Format</code> button to format JSON lines. This also soft wraps inner json fields like <code>message</code> and <code>stack_trace</code> making it easier to inspect the contents.</p><h3 id="view-options" tabindex="-1">View Options <a class="header-anchor" href="#view-options" aria-label="Permalink to &quot;View Options&quot;">​</a></h3><p>Customize how logs are displayed:</p><h4 id="wrap-lines-w" tabindex="-1">Wrap Lines (<code>W</code>) <a class="header-anchor" href="#wrap-lines-w" aria-label="Permalink to &quot;Wrap Lines (`W`)&quot;">​</a></h4><p>Toggle line wrapping for long log entries:</p><ul><li><strong>On</strong>: Long lines wrap to fit the window</li><li><strong>Off</strong>: Horizontal scroll for long lines</li></ul><h4 id="show-timestamps-t" tabindex="-1">Show Timestamps (<code>T</code>) <a class="header-anchor" href="#show-timestamps-t" aria-label="Permalink to &quot;Show Timestamps (`T`)&quot;">​</a></h4><p>Toggle timestamp display:</p><ul><li><strong>On</strong>: Each line shows its timestamp</li><li><strong>Off</strong>: Clean view without timestamps</li></ul><h4 id="auto-scroll-a" tabindex="-1">Auto-Scroll (<code>A</code>) <a class="header-anchor" href="#auto-scroll-a" aria-label="Permalink to &quot;Auto-Scroll (`A`)&quot;">​</a></h4><p>Toggle automatic scrolling:</p><ul><li><strong>On</strong>: View follows new log entries</li><li><strong>Off</strong>: Stay at current position while reviewing</li></ul><h3 id="copy-logs-c" tabindex="-1">Copy Logs (<code>C</code>) <a class="header-anchor" href="#copy-logs-c" aria-label="Permalink to &quot;Copy Logs (`C`)&quot;">​</a></h3><p>Copy the visible log content to your clipboard for sharing or analysis.</p><h2 id="keyboard-shortcuts" tabindex="-1">Keyboard Shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard Shortcuts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>W</code></td><td>Toggle line wrap</td></tr><tr><td><code>T</code></td><td>Toggle timestamps</td></tr><tr><td><code>A</code></td><td>Toggle auto-scroll</td></tr><tr><td><code>C</code></td><td>Copy logs to clipboard</td></tr><tr><td><code>Ctrl+R</code></td><td>Restart log stream</td></tr><tr><td><code>Esc</code></td><td>Close log viewer</td></tr><tr><td><code>↑</code> <code>↓</code></td><td>Scroll (when auto-scroll off)</td></tr><tr><td><code>Page Up</code> / <code>Page Down</code></td><td>Fast scroll</td></tr></tbody></table><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Following Multiple Containers</p><p>For multi-container pods, open separate log viewers by navigating to each container individually.</p></div>',30)])])}const u=t(r,[["render",l]]);export{g as __pageData,u as default};
